// LoadPool loads the fundingObligation's Pool into the .R struct
func (os FundingObligationSlice) LoadPool(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	pools, err := os.Pool(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Pool = nil
		o.R.Loaded.Pool = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range pools {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !(o.PoolID == rel.ID) {
				continue
			}

			rel.R.FundingObligations = append(rel.R.FundingObligations, o)

			o.R.Pool = rel
			break
		}
	}

	return nil
}

