// LoadScheduleFundingSchedule loads the fundingObligation's ScheduleFundingSchedule into the .R struct
func (os FundingObligationSlice) LoadScheduleFundingSchedule(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	fundingSchedules, err := os.ScheduleFundingSchedule(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.ScheduleFundingSchedule = nil
		o.R.Loaded.ScheduleFundingSchedule = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	fundingObligationByKey := make(map[uuid.UUID][]*FundingObligation, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		// NULL never matches any row in SQL, so don't add it to the map
		if !o.ScheduleID.Valid {
			continue
		}

		fundingObligationByKey[o.ScheduleID.V] = append(fundingObligationByKey[o.ScheduleID.V], o)
	}

	for _, rel := range fundingSchedules {

		owners, ok := fundingObligationByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.ScheduleFundingSchedule != nil {
				continue
			}

			rel.R.ScheduleFundingObligations = append(rel.R.ScheduleFundingObligations, o)

			o.R.ScheduleFundingSchedule = rel

		}
	}

	return nil
}

type fundingObligationJoins[Q dialect.Joinable] struct {
	typ                     string
	Household               modAs[Q, householdColumns]
	Pool                    modAs[Q, poolColumns]
	Member                  modAs[Q, memberColumns]
	ScheduleFundingSchedule modAs[Q, fundingScheduleColumns]
}

func (j fundingObligationJoins[Q]) aliasedAs(alias string) fundingObligationJoins[Q] {
	return buildFundingObligationJoins[Q](buildFundingObligationColumns(alias), j.typ)
}

func buildFundingObligationJoins[Q dialect.Joinable](cols fundingObligationColumns, typ string) fundingObligationJoins[Q] {
	return fundingObligationJoins[Q]{
		typ: typ,
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
		Pool: modAs[Q, poolColumns]{
			c: Pools.Columns,
			f: func(to poolColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Pools.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.PoolID),
					))
				}

				return mods
			},
		},
		Member: modAs[Q, memberColumns]{
			c: Members.Columns,
			f: func(to memberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Members.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.MemberID),
					))
				}

				return mods
			},
		},
		ScheduleFundingSchedule: modAs[Q, fundingScheduleColumns]{
			c: FundingSchedules.Columns,
			f: func(to fundingScheduleColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, FundingSchedules.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.ScheduleID),
					))
				}

				return mods
			},
		},
	}
}
